const input = $input.all().map((item) => item.json);
const rows = input.length ? input : [
  { record_id: 'A-001', customer_name: 'Example One', total: '12.50', observed_at: '2026-09-15' },
  { record_id: 'A-002', customer_name: 'Example Two', total: '8.00', observed_at: '2026-09-15' }
];

const seen = new Set();
return rows.map((row, index) => {
  const recordId = String(row.record_id ?? '').trim();
  const duplicate = !recordId || seen.has(recordId);
  if (recordId) seen.add(recordId);
  return {
    json: {
      ...row,
      record_id: recordId,
      total: row.total === '' || row.total == null ? null : Number(row.total),
      import_action: duplicate ? 'review' : 'candidate',
      import_reason: !recordId ? 'missing stable record_id' : duplicate ? 'duplicate record_id in input' : 'ready for destination lookup',
      source_row: index + 1
    }
  };
});
